using Microsoft.VisualStudio.TestTools.UnitTesting;
using Store;

namespace Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem ---

    [TestMethod]
    [DataRow("SKU1", 1, 9.99)]
    [DataRow("SKU2", 5, 0.00)]
    [DataRow("SKU3", 100, 49.95)]
    public void AddItem_ValidInputs_DoesNotThrow(string sku, int qty, double price)
    {
        _cart.AddItem(sku, qty, (decimal)price);
        // No exception means success; verify via total
        Assert.AreEqual((decimal)price * qty, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _cart.AddItem("A", 2, 10m);
        _cart.AddItem("A", 3, 10m);

        // 5 units at $10
        Assert.AreEqual(50m, _cart.CalculateTotal());
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.AddItem(sku!, 1, 5m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_InvalidQuantity_Throws(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _cart.AddItem("X", qty, 5m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _cart.AddItem("X", 1, -1m));
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.RemoveItem("A");

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFound()
    {
        Assert.ThrowsException<KeyNotFoundException>(() => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void RemoveItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.RemoveItem(sku!));
    }

    // --- CalculateTotal ---

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_SumsCorrectly()
    {
        _cart.AddItem("A", 2, 5m);   // 10
        _cart.AddItem("B", 1, 20m);  // 20

        Assert.AreEqual(30m, _cart.CalculateTotal());
    }

    // --- ApplyCoupon ---

    [TestMethod]
    [DataRow("SAVE10", 10.0)]
    [DataRow("save10", 10.0)]
    [DataRow("SAVE20", 20.0)]
    [DataRow("HALF", 50.0)]
    public void ApplyCoupon_ValidCode_AppliesDiscount(string code, double discountPct)
    {
        _cart.AddItem("A", 1, 100m);
        _cart.ApplyCoupon(code);

        var expected = 100m - (100m * (decimal)discountPct / 100m);
        Assert.AreEqual(expected, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_Throws()
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon("BOGUS"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void ApplyCoupon_NullOrEmpty_Throws(string? code)
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_AppliedAfterAddingItems_AffectsTotal()
    {
        _cart.AddItem("A", 2, 50m); // subtotal 100
        _cart.ApplyCoupon("SAVE20"); // 20% off

        Assert.AreEqual(80m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_SecondCoupon_OverridesFirst()
    {
        _cart.AddItem("A", 1, 100m);
        _cart.ApplyCoupon("SAVE10"); // 10% → $90
        _cart.ApplyCoupon("HALF");   // 50% → $50

        Assert.AreEqual(50m, _cart.CalculateTotal());
    }
}

